create table if not exists public.vehicle_image_review_baselines (asset_id bigint primary key references public.vehicle_image_assets(id) on delete restrict, image_path text not null unique, git_blob_sha text not null check (git_blob_sha ~ '^[0-9a-f]{40}$'), git_commit_sha text not null check (git_commit_sha ~ '^[0-9a-f]{40}$'), metadata_lock_eligible boolean not null default false, recorded_at timestamptz not null default now()); alter table public.vehicle_image_review_baselines enable row level security; comment on table public.vehicle_image_review_baselines is 'Review snapshot only: Git blob SHA baseline. This does not by itself enforce Git image immutability or guarantee realtime identity.'
